import ast,pathlib,re
base=pathlib.Path('/app/code/src/reward_relative')
terms=re.compile(r'(trial|reward|lick|speed|position|pos|dff|event|spk|cell|neuropil|iscell|teleport|frame|VR|timeseries|mask|exclude|filter|baseline)',re.I)
for fn in ['preprocessing.py','behavior.py','spatial.py','utilities.py']:
 p=base/fn; src=p.read_text(); lines=src.splitlines(); tree=ast.parse(src)
 print('\n###',fn)
 for n in ast.walk(tree):
  if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and (fn=='preprocessing.py' or terms.search(n.name)):
   sig=lines[n.lineno-1].strip()
   doc=ast.get_docstring(n) or ''
   relevant=[]
   for no in range(n.lineno,min(n.end_lineno,n.lineno+350)+1):
    line=lines[no-1]
    if terms.search(line) and not line.lstrip().startswith(('#',':param')):
     relevant.append(f'{no}: {line.strip()}')
   print(f'-- {sig} [{n.lineno}-{n.end_lineno}]')
   if doc: print('DOC:',doc.split('\n')[0][:180])
   print('\n'.join(relevant[:45]))
